  bytes_at bsegs m (bv_unsigned a0) [Z_to_bv 8 45; Z_to_bv 8 49; Z_to_bv 8 0] ->
  0x684000 <= bv_unsigned a0 -> bv_unsigned a0 + 3 <= 0x7fffffffffff ->
  (bv_unsigned a0 + 3 <= lo \/ bv_unsigned sp <= bv_unsigned a0) ->
  rw_cells bsegs m (bv_unsigned a1) [C8 e0] ->
  0x684000 <= bv_unsigned a1 -> bv_unsigned a1 + 8 <= 0x7fffffffffff ->
  (bv_unsigned a1 + 8 <= lo \/ bv_unsigned sp <= bv_unsigned a1) ->
  (bv_unsigned a0 + 3 <= bv_unsigned a1 \/ bv_unsigned a1 + 8 <= bv_unsigned a0) ->
  rw_cells bsegs m AGOT_SSP [C8 (Z_to_bv 64 A_STKCHK_GUARD)] -> acanary m -> mem_inv bsegs m ->
  evt bsegs (rstrtoll_m1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a0 a1 lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
